-- ============================================================
-- AEGISORA ENTERPRISE TENANT ISOLATION HARDENING
-- Generated by Phase 3.4
--
-- IMPORTANT:
-- Review against the deployed schema before applying remotely.
-- This migration intentionally does NOT alter application data.
-- ============================================================

begin;

-- ============================================================
-- 1. MEMBERSHIP HELPERS
-- ============================================================

create or replace function public.is_member(ws uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pg_catalog
as $$
  select exists (
    select 1
    from public.workspace_members m
    where m.workspace_id = ws
      and m.user_id = auth.uid()
      and coalesce(m.status::text, 'active') = 'active'
  );
$$;

create or replace function public.has_role(
  ws uuid,
  roles text[]
)
returns boolean
language sql
stable
security definer
set search_path = public, pg_catalog
as $$
  select exists (
    select 1
    from public.workspace_members m
    where m.workspace_id = ws
      and m.user_id = auth.uid()
      and coalesce(m.status::text, 'active') = 'active'
      and upper(m.role::text) = any (
        select upper(r)
        from unnest(roles) as r
      )
  );
$$;

revoke all on function public.is_member(uuid) from public;
revoke all on function public.has_role(uuid, text[]) from public;

grant execute on function public.is_member(uuid) to authenticated;
grant execute on function public.has_role(uuid, text[]) to authenticated;

-- ============================================================
-- 2. ENABLE + FORCE RLS
-- ============================================================

alter table public.agents enable row level security;
alter table public.agents force row level security;

alter table public.api_keys enable row level security;
alter table public.api_keys force row level security;

alter table public.approvals enable row level security;
alter table public.approvals force row level security;

alter table public.audit_events enable row level security;
alter table public.audit_events force row level security;

alter table public.decisions enable row level security;
alter table public.decisions force row level security;

alter table public.evidence enable row level security;
alter table public.evidence force row level security;

alter table public.incidents enable row level security;
alter table public.incidents force row level security;

alter table public.policies enable row level security;
alter table public.policies force row level security;

alter table public.traces enable row level security;
alter table public.traces force row level security;

alter table public.webhooks enable row level security;
alter table public.webhooks force row level security;

alter table public.workspace_settings enable row level security;
alter table public.workspace_settings force row level security;

alter table public.workspace_members enable row level security;
alter table public.workspace_members force row level security;

alter table public.workspaces enable row level security;
alter table public.workspaces force row level security;

alter table public.profiles enable row level security;
alter table public.profiles force row level security;

-- ============================================================
-- 3. REMOVE OLD POLICIES
-- ============================================================

do $$
declare
  r record;
begin
  for r in
    select schemaname, tablename, policyname
    from pg_policies
    where schemaname = 'public'
      and tablename in (
        'agents',
        'api_keys',
        'approvals',
        'audit_events',
        'decisions',
        'evidence',
        'incidents',
        'policies',
        'traces',
        'webhooks',
        'workspace_settings',
        'workspace_members',
        'workspaces',
        'profiles'
      )
  loop
    execute format(
      'drop policy if exists %I on %I.%I',
      r.policyname,
      r.schemaname,
      r.tablename
    );
  end loop;
end
$$;

-- ============================================================
-- 4. AGENTS
-- ============================================================

create policy agents_select
on public.agents
for select
to authenticated
using (
  public.is_member(workspace_id)
);

create policy agents_insert
on public.agents
for insert
to authenticated
with check (
  public.has_role(
    workspace_id,
    array['OWNER','ADMIN','DEVELOPER']
  )
);

create policy agents_update
on public.agents
for update
to authenticated
using (
  public.has_role(
    workspace_id,
    array['OWNER','ADMIN','DEVELOPER']
  )
)
with check (
  public.has_role(
    workspace_id,
    array['OWNER','ADMIN','DEVELOPER']
  )
);

create policy agents_delete
on public.agents
for delete
to authenticated
using (
  public.has_role(
    workspace_id,
    array['OWNER','ADMIN','DEVELOPER']
  )
);

